{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MapleMonk.Zouk_D2C_Revenue_Performance AS WITH Targets AS ( SELECT DATE_ADD(DATE(t.Start_Date), INTERVAL n DAY) AS Date, t.Type, CAST(REPLACE(t.Target, \',\', \'\') AS FLOAT64) / (DATE_DIFF(DATE(t.End_Date), DATE(t.Start_Date), DAY) + 1) AS Daily_Target FROM `MapleMonk.Zouk_Sales_Target` t, UNNEST(GENERATE_ARRAY(0, DATE_DIFF(DATE(t.End_Date), DATE(t.Start_Date), DAY))) AS n ), Affiliate_Sales_Daily AS ( SELECT DATE_ADD(DATE(a.Start_Date), INTERVAL n DAY) AS Date, CAST(a.Revenue AS FLOAT64) / (DATE_DIFF(DATE(a.End_Date), DATE(a.Start_Date), DAY) + 1) AS Revenue, CAST(a.Net_Revenue AS FLOAT64) / (DATE_DIFF(DATE(a.End_Date), DATE(a.Start_Date), DAY) + 1) AS Net_Revenue FROM `MapleMonk.Zouk_Affiliate_Sales` a, UNNEST(GENERATE_ARRAY(0, DATE_DIFF(DATE(a.End_Date), DATE(a.Start_Date), DAY))) AS n ), DTC_PandL AS ( SELECT Date, FINAL_MARKETPLACE, new_customer_flag, SUM(IFNULL(BAU_MRP_SALES, 0)) - SUM(IFNULL(BAU_DISCOUNT, 0)) - SUM(IFNULL(return_mrp_sales, 0)) AS MRP_Sales, SUM(IFNULL(BAU_MRP_SALES, 0)) - SUM(IFNULL(return_mrp_sales, 0)) - SUM(IFNULL(BAU_DISCOUNT, 0)) - SUM(IFNULL(TRADE_MARGIN, 0)) + SUM(IFNULL(return_trade_margin, 0)) - SUM(IFNULL(Returns, 0)) - SUM(IFNULL(gst, 0)) + SUM(IFNULL(Return_GST, 0)) AS Net_Revenue FROM `MapleMonk.zouk_pandl_DTC` GROUP BY Date, FINAL_MARKETPLACE, new_customer_flag ), Metric_DTC_MRP AS ( SELECT d.Date, \'DTC MRP\' AS Metric, t.Daily_Target AS Target, SUM(d.MRP_Sales) AS Actual FROM DTC_PandL d LEFT JOIN Targets t ON d.Date = t.Date AND lower(t.Type) like \'mrp\' GROUP BY d.Date, t.Daily_Target ), Metric_DTC_NetRevenue AS ( SELECT d.Date, \'DTC Revenue\' AS Metric, t.Daily_Target AS Target, SUM(d.Net_Revenue) AS Actual FROM DTC_PandL d LEFT JOIN Targets t ON d.Date = t.Date AND lower(t.Type) like \'net mrp\' GROUP BY d.Date, t.Daily_Target ), Metric_App_Revenue AS ( SELECT d.Date, \'App Revenue\' AS Metric, t.Daily_Target AS Target, SUM(CASE WHEN LOWER(d.FINAL_MARKETPLACE) LIKE \'%app%\' THEN d.Net_Revenue ELSE 0 END) AS Actual FROM DTC_PandL d LEFT JOIN Targets t ON d.Date = t.Date AND lower(t.Type) like \'%app%\' GROUP BY d.Date, t.Daily_Target ), Metric_New_User_Revenue AS ( SELECT d.Date, \'New User Revenue\' AS Metric, t.Daily_Target AS Target, SUM(CASE WHEN LOWER(d.new_customer_flag) = \'new\' THEN d.Net_Revenue ELSE 0 END) AS Actual FROM DTC_PandL d LEFT JOIN Targets t ON d.Date = t.Date AND lower(t.Type) like \'%new%\' GROUP BY d.Date, t.Daily_Target ), Metric_Repeat_User_Revenue AS ( SELECT d.Date, \'Repeat User Revenue\' AS Metric, t.Daily_Target AS Target, SUM(CASE WHEN LOWER(d.new_customer_flag) = \'repeat\' THEN d.Net_Revenue ELSE 0 END) AS Actual FROM DTC_PandL d LEFT JOIN Targets t ON d.Date = t.Date AND lower(t.Type) like \'%retention%\' GROUP BY d.Date, t.Daily_Target ), Metric_Affiliate_Revenue AS ( SELECT a.Date, \'Affiliate Revenue\' AS Metric, t.Daily_Target AS Target, SUM(a.Net_Revenue) AS Actual FROM Affiliate_Sales_Daily a LEFT JOIN Targets t ON a.Date = t.Date AND lower(t.Type) like \'%affliates%\' GROUP BY a.Date, t.Daily_Target ) SELECT * FROM Metric_DTC_NetRevenue UNION ALL SELECT * FROM Metric_DTC_MRP UNION ALL SELECT * FROM Metric_App_Revenue UNION ALL SELECT * FROM Metric_New_User_Revenue UNION ALL SELECT * FROM Metric_Repeat_User_Revenue UNION ALL SELECT * FROM Metric_Affiliate_Revenue ORDER BY Date, Metric;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            